#!/bin/bash -eu
# Generated by fuzzbench_generate.py for bug transplant evaluation

cd /src/opensc

# Checkout target commit
git checkout 6903aebfddc466d966c7b865fae34572bf3ed23e

# Apply dispatch harness first (modifies build system), then bug patches
if ! git apply --check /src/patches/harness.diff 2>/dev/null; then
    echo "Trying git apply --3way for harness.diff..."
    git apply --3way /src/patches/harness.diff
else
    git apply /src/patches/harness.diff
fi

if ! git apply --check /src/patches/combined.diff 2>/dev/null; then
    echo "Trying git apply --3way for combined.diff..."
    git apply --3way /src/patches/combined.diff
else
    git apply /src/patches/combined.diff
fi

# --- Original build commands ---
# Regenerate autotools to fix libtool compatibility with clang
autoreconf -fiv

# Build the library (but fuzzer linking will fail with C linker, so we handle that)
./configure --disable-strict --disable-optimization --disable-shared --disable-pcsc \
  --enable-ctapi --enable-fuzzing \
  CC="$CC" CXX="$CXX" \
  FUZZING_LIBS="$LIB_FUZZING_ENGINE -lstdc++"

# Resolve the actual fuzzing engine library path
FUZZ_LIB="${LIB_FUZZING_ENGINE:-}"
if [ ! -f "$FUZZ_LIB" ]; then
    # FuzzBench coverage build uses /usr/lib/libFuzzer.a
    for candidate in /usr/lib/libFuzzer.a /usr/lib/libFuzzingEngine.a; do
        if [ -f "$candidate" ]; then
            FUZZ_LIB="$candidate"
            break
        fi
    done
fi
echo "Using fuzzing engine: $FUZZ_LIB"

# Build library and object files; ignore link errors from fuzz targets
# (autotools links fuzzers with cc but the engine needs c++; we relink below)
set +e
make -j$(nproc)
make -j1
set -e

# Manually link fuzz targets with CXX to resolve C++ stdlib from the fuzzing engine
fuzzerFiles=$(find $SRC/opensc/src/tests/fuzzing/ -name "fuzz_*.c")

for F in $fuzzerFiles; do
    fuzzerName=$(basename $F .c)

    # Compile the fuzzer source if .o doesn't exist
    if [ ! -f src/tests/fuzzing/${fuzzerName}.o ]; then
        $CC $CFLAGS -I src -I src/libopensc \
          -c src/tests/fuzzing/${fuzzerName}.c \
          -o src/tests/fuzzing/${fuzzerName}.o
    fi

    # Link with CXX (resolves C++ symbols from the fuzzing engine)
    $CXX $CXXFLAGS -o $OUT/$fuzzerName \
      src/tests/fuzzing/${fuzzerName}.o \
      src/libopensc/.libs/libopensc.a \
      src/common/.libs/libscdl.a \
      src/common/.libs/libcompat.a \
      $FUZZ_LIB \
      -lcrypto -lz -ldl -lpthread -lstdc++ || echo "WARN: Failed to link $fuzzerName"

    if [ -d "src/tests/fuzzing/corpus/${fuzzerName}" ]; then
        zip -j $OUT/${fuzzerName}_seed_corpus.zip src/tests/fuzzing/corpus/${fuzzerName}/*
    fi
done

# --- Seed corpus: prepend dispatch bytes to original seeds ---
mkdir -p /tmp/seeds_dispatch

if [ -f "$OUT/fuzz_pkcs15_reader_seed_corpus.zip" ]; then
    mkdir -p /tmp/original_seeds
    unzip -q -o "$OUT/fuzz_pkcs15_reader_seed_corpus.zip" -d /tmp/original_seeds 2>/dev/null || true
    for f in /tmp/original_seeds/*; do
        [ -f "$f" ] && printf '\x00' | cat - "$f" > "/tmp/seeds_dispatch/$(basename "$f")"
    done
fi

if ls /tmp/seeds_dispatch/* 1>/dev/null 2>&1; then
    zip -j -q "$OUT/fuzz_pkcs15_reader_seed_corpus.zip" /tmp/seeds_dispatch/*
fi
